import {useScrollLock} from '@astryxdesign/core/hooks';
import {useFocusTrapEscapeCompatibilitySignal} from '../hooks/useFocusTrap';
import {dispatchLayerEscapeKeyDown} from '../Layer/layerStack';
import {useLayerDismissal} from '@astryxdesign/core/Layer';
import {composeEventHandlers} from '@astryxdesign/core/utils';
import {mergeRefs} from '@astryxdesign/core/utils';
import {useModalOutletWithoutRef} from '../Layer/modalOutlet';
import {BottomSheetHostContext} from './BottomSheetHostContext';
import {
  BOTTOM_SHEET_STACK_DEFAULT_VIEW,
  cancelScrimWrite,
  closeDialogKeepingFocus,
  focusSheetPanel,
  getBottomSheetBeneath,
  isClosingTogether,
  notifyBottomSheetHostChanged,
  presentStepModally,
  presentWithClearScrim,
