export function distanceIntoBand(
  top: number,
  bottom: number,
  safeTop: number,
  safeBottom: number,
): number {
  if (safeBottom <= safeTop) {
    return 0;
  }
  if (bottom > safeBottom) {
    return bottom - safeBottom;
  }
  if (top < safeTop) {
