export function selectSnapPoint(
  points: ReadonlyArray<number>,
  {
    position,
    velocity,
    rate = scroll.decelerationRate.normal,
    fromIndex,
    maxSteps,
  }: {
    position: number;
    velocity: number;
    rate?: number;
    fromIndex?: number;
    maxSteps?: number;
  },
): SnapSelection {
