export function planReducedMotion(
  view: ReducedMotionView,
  time: number,
  targets: Partial<Record<MotionProperty, number>>,
  properties: ReadonlyArray<MotionProperty>,
  fade: boolean,
  role?: 'entrance' | 'exit',
): ReducedMotionPlan {
