  const opacityTo = targets.opacity ?? view.opacityHeading();
  const travel = properties.filter(
    property =>
      TRAVEL_PROPERTIES.includes(property) &&
      Math.abs((targets[property] as number) - view.valueAt(property, time)) >
        1e-9,
  );
