    ownerDocument == null ||
    (typeof document !== 'undefined' && ownerDocument === document)
  ) {
    return undefined;
  }
  const release = trackInteractionModalityIn(ownerDocument);
  previous.release = release;
  return () => {
    release();
    if (previous.release === release) {
      previous.release = null;
    }
